class Solution {
  public int wateringPlants(int[] plants, int capacity) {
    int steps = 0, water = capacity;
    for (int i = 0; i < plants.length; i++) {
      if (water < plants[i]) {
        steps += 2 * i; // walk back to the river and return to the same spot
        water = capacity;
      }
      water -= plants[i];
      steps++;
    }
    return steps;
  }
}
